      { "AssertionId": "H25", "Statement": "Some left-edge diagonal with k < 20000 has least eventual period 32.", "ReportedStatus": "FALSIFIED", "ProofSection": "", "Kind": "Hypothesis", "IntroducedInLoop": "effortless-12", "Name": "H25", "StatusGroup": "Falsified", "PremiseCount": 1, "DependentCount": 0, "EvidenceCount": 1, "RevisionCount": 1, "IsUsable": 0, "IsProofEligible": 0, "DescendantCount": 0, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "F11", "Statement": "Exact left-edge periods and onsets certified for k<=19999; for every 20<=k<=19999 the onset exceeds k, so the center c(t)=w_t(t) is read before its left-edge diagonal settles.", "ReportedStatus": "FINITE_VERIFIED", "ProofSection": "", "Kind": "Finite check", "IntroducedInLoop": "effortless-12", "Name": "F11", "StatusGroup": "Checked", "PremiseCount": 1, "DependentCount": 2, "EvidenceCount": 1, "RevisionCount": 0, "IsUsable": 1, "IsProofEligible": 0, "DescendantCount": 2, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "TS", "Statement": "If the center p-agrees at t and t+1 then column -1 p-agrees at t when c(t)=1, and column -1 p-agrees at t iff column 1 does when c(t)=0: under center agreement, column -1 is column 1 read at the center's zero-times.", "ReportedStatus": "PROVED_HUMAN_READABLE", "ProofSection": "research/loop-13-top-down/PROOFS.md \u00a7TS", "Kind": "Theorem", "IntroducedInLoop": "effortless-13", "Name": "TS", "StatusGroup": "Proved", "PremiseCount": 1, "DependentCount": 6, "EvidenceCount": 1, "RevisionCount": 0, "IsUsable": 1, "IsProofEligible": 1, "DescendantCount": 30, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "H26", "Statement": "For every onset 1<=T<=10 and every nonconstant primitive word a of period p<=4, the left cone and the inverse rule alone exclude a p-periodic center of word a from onset T: no column-1 window is compatible once L reaches some L<=4T+4p+8.", "ReportedStatus": "FINITE_VERIFIED", "ProofSection": "", "Kind": "Hypothesis", "IntroducedInLoop": "effortless-13", "Name": "H26", "StatusGroup": "Checked", "PremiseCount": 3, "DependentCount": 0, "EvidenceCount": 1, "RevisionCount": 1, "IsUsable": 1, "IsProofEligible": 0, "DescendantCount": 0, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "F12", "Statement": "Left-cone relaxation table for every onset T<=10 and every primitive word of period <=4: the number of column-1 windows (on the zero-times) compatible with a periodic center and the single-seed cone, for L<=4T+4p+8, with the first L that has none; the true (c,r) windows pass the same checker.", "ReportedStatus": "FINITE_VERIFIED", "ProofSection": "", "Kind": "Finite check", "IntroducedInLoop": "effortless-13", "Name": "F12", "StatusGroup": "Checked", "PremiseCount": 2, "DependentCount": 0, "EvidenceCount": 1, "RevisionCount": 0, "IsUsable": 1, "IsProofEligible": 0, "DescendantCount": 0, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "B5", "Statement": "For every onset T, every p>=2 and every nonconstant word a of least period p, the left-cone relaxation (periodic center word a from T, free column 1, inverse rule, cone of T0) is unsatisfiable at some finite L(T,a).", "ReportedStatus": "PROVED_HUMAN_READABLE", "ProofSection": "research/loop-17-affine/PROOFS.md \u00a7B6", "Kind": "Bridge obligation", "IntroducedInLoop": "effortless-13", "Name": "B5", "StatusGroup": "Proved", "PremiseCount": 5, "DependentCount": 2, "EvidenceCount": 8, "RevisionCount": 1, "IsUsable": 1, "IsProofEligible": 1, "DescendantCount": 3, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "TU", "Statement": "For L>=T the left-cone relaxation is in bijection with rows R at time T on positions -T+1..-1 such that the Rule 30 evolution of the left half from R, with the center prescribed as boundary x(0,t)=c'(t), satisfies x(-1,t)=NOT c'(t+1) at every one-time t<=T+L-1; column 1 is determined, and count(T,a,L)<=2^(T-1).", "ReportedStatus": "PROVED_HUMAN_READABLE", "ProofSection": "research/loop-14-left-cone-growth/PROOFS.md \u00a7TU", "Kind": "Theorem", "IntroducedInLoop": "effortless-14", "Name": "TU", "StatusGroup": "Proved", "PremiseCount": 3, "DependentCount": 23, "EvidenceCount": 1, "RevisionCount": 0, "IsUsable": 1, "IsProofEligible": 1, "DescendantCount": 27, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "H27", "Statement": "For every primitive nonconstant word a of period p<=6 and every onset 2<=T<=T_max(a) that exact enumeration completes (live-set cap 2^23), the left cone excludes the periodic center with L(T,a)<=4T+4p+8.", "ReportedStatus": "FINITE_VERIFIED", "ProofSection": "", "Kind": "Hypothesis", "IntroducedInLoop": "effortless-14", "Name": "H27", "StatusGroup": "Checked", "PremiseCount": 3, "DependentCount": 0, "EvidenceCount": 1, "RevisionCount": 1, "IsUsable": 1, "IsProofEligible": 0, "DescendantCount": 0, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "F13", "Statement": "Exclusion lengths L(T,a) of the left-cone relaxation for every primitive word of period <=6, onsets from 2 up to the enumeration limit per word (largest completed onset 144); vectorised search validated against the loop 13 table and an independent SAT encoding of TU.", "ReportedStatus": "FINITE_VERIFIED", "ProofSection": "", "Kind": "Finite check", "IntroducedInLoop": "effortless-14", "Name": "F13", "StatusGroup": "Checked", "PremiseCount": 3, "DependentCount": 0, "EvidenceCount": 1, "RevisionCount": 0, "IsUsable": 1, "IsProofEligible": 0, "DescendantCount": 0, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "TV", "Statement": "For t>=T and j<=t-T, x(-1,t) = x(-j-1,t-j) XOR XOR_{i=1..j}(x(-i,t-i) OR x(-i+1,t-i)); in the relaxation the leading term is a free row bit for t<=2T-2, the edge for t=2T-1 and 0 for t>=2T, so every one-time constraint from time 2T on is a parity of ORs along a light ray with no free-row term.", "ReportedStatus": "PROVED_HUMAN_READABLE", "ProofSection": "research/loop-15-bounded-excess/PROOFS.md \u00a7TV", "Kind": "Theorem", "IntroducedInLoop": "effortless-15", "Name": "TV", "StatusGroup": "Proved", "PremiseCount": 3, "DependentCount": 10, "EvidenceCount": 1, "RevisionCount": 0, "IsUsable": 1, "IsProofEligible": 1, "DescendantCount": 21, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "H28", "Statement": "For every primitive nonconstant word of period 7 or 8 and every onset T>=8 that exact enumeration completes (cap 2^23), the left-cone exclusion excess L(T,a)-T is at most 64: the relaxation dies by time 2T+64, independently of T.", "ReportedStatus": "FINITE_VERIFIED", "ProofSection": "", "Kind": "Hypothesis", "IntroducedInLoop": "effortless-15", "Name": "H28", "StatusGroup": "Checked", "PremiseCount": 3, "DependentCount": 0, "EvidenceCount": 1, "RevisionCount": 1, "IsUsable": 1, "IsProofEligible": 0, "DescendantCount": 0, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "F14", "Statement": "Exclusion lengths, death times and violated cone cells of the left-cone relaxation for all 366 primitive words of periods 7 and 8 at onsets [8, 16, 24, 32, 48, 64, 96, 128, 160, 192] up to the enumeration limit (largest completed 192); death-cell histograms recorded.", "ReportedStatus": "FINITE_VERIFIED", "ProofSection": "", "Kind": "Finite check", "IntroducedInLoop": "effortless-15", "Name": "F14", "StatusGroup": "Checked", "PremiseCount": 3, "DependentCount": 0, "EvidenceCount": 1, "RevisionCount": 0, "IsUsable": 1, "IsProofEligible": 0, "DescendantCount": 0, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "H29", "Statement": "For the single-zero words a=0 1^(p-1), p in [8, 10, 12, 16], and every onset T>=32 that exact enumeration completes (cap 2^25), the left-cone exclusion excess L(T,a)-T is at most 64.", "ReportedStatus": "FINITE_VERIFIED", "ProofSection": "", "Kind": "Hypothesis", "IntroducedInLoop": "effortless-16", "Name": "H29", "StatusGroup": "Checked", "PremiseCount": 3, "DependentCount": 0, "EvidenceCount": 2, "RevisionCount": 1, "IsUsable": 1, "IsProofEligible": 0, "DescendantCount": 0, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "F15", "Statement": "Exclusion lengths, excess and death cells of the left-cone relaxation for the single-zero words of periods [8, 10, 12, 16] at onsets from 32 to the enumeration limit (largest completed 384), with the excess fitted against T and log2 T.", "ReportedStatus": "FINITE_VERIFIED", "ProofSection": "", "Kind": "Finite check", "IntroducedInLoop": "effortless-16", "Name": "F15", "StatusGroup": "Checked", "PremiseCount": 3, "DependentCount": 0, "EvidenceCount": 1, "RevisionCount": 0, "IsUsable": 1, "IsProofEligible": 0, "DescendantCount": 0, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "TW", "Statement": "In the forward form, the one-time constraints at T<=t<=2T-2 fix the row bit at position -(t-T+1) as a function of the bits to its right and leave the bits at zero-time positions free: exactly 2^Z rows survive to 2T-2 (Z = zero-times in [T,2T-2]), and every constraint at t>=2T-1 is a Boolean function of those Z bits.", "ReportedStatus": "PROVED_HUMAN_READABLE", "ProofSection": "research/loop-17-affine/PROOFS.md \u00a7TW", "Kind": "Theorem", "IntroducedInLoop": "effortless-17", "Name": "TW", "StatusGroup": "Proved", "PremiseCount": 4, "DependentCount": 12, "EvidenceCount": 2, "RevisionCount": 0, "IsUsable": 1, "IsProofEligible": 1, "DescendantCount": 15, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "B6", "Statement": "For every T>=2 and every nonconstant periodic word, each of the 2^Z rows of TW violates x(-1,t)=NOT c'(t+1) at some one-time t>=2T-1.", "ReportedStatus": "PROVED_HUMAN_READABLE", "ProofSection": "research/loop-19-period-2/PROOFS.md \u00a7Why period 2 first", "Kind": "Bridge obligation", "IntroducedInLoop": "effortless-17", "Name": "B6", "StatusGroup": "Proved", "PremiseCount": 5, "DependentCount": 1, "EvidenceCount": 3, "RevisionCount": 1, "IsUsable": 1, "IsProofEligible": 1, "DescendantCount": 4, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "H30", "Statement": "For every nonconstant primitive word of period p<=5 and every onset 4<=T<=18, the largest algebraic degree over the Z free bits among the one-time constraints applied before death is at least Z-1: the kill is maximally nonlinear, so B6 is not linear algebra over GF(2).", "ReportedStatus": "FALSIFIED", "ProofSection": "", "Kind": "Hypothesis", "IntroducedInLoop": "effortless-17", "Name": "H30", "StatusGroup": "Falsified", "PremiseCount": 2, "DependentCount": 0, "EvidenceCount": 1, "RevisionCount": 1, "IsUsable": 0, "IsProofEligible": 0, "DescendantCount": 0, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "F16", "Statement": "For every nonconstant primitive word of period <=5 and onset 4..18: Z, the TW count check, and for each one-time constraint after 2T-2 until death its algebraic degree over the Z free bits, live counts before and after, and whether it was constant on the live set.", "ReportedStatus": "FINITE_VERIFIED", "ProofSection": "", "Kind": "Finite check", "IntroducedInLoop": "effortless-17", "Name": "F16", "StatusGroup": "Checked", "PremiseCount": 2, "DependentCount": 0, "EvidenceCount": 1, "RevisionCount": 0, "IsUsable": 1, "IsProofEligible": 0, "DescendantCount": 0, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "H31", "Statement": "For the words 01 and 10 and every onset 4<=T<=46, a cone cell violated by every surviving window exists at the death step, and its time t*(T) is non-decreasing in T with steps 0 or 1.", "ReportedStatus": "FALSIFIED", "ProofSection": "", "Kind": "Hypothesis", "IntroducedInLoop": "effortless-18", "Name": "H31", "StatusGroup": "Falsified", "PremiseCount": 4, "DependentCount": 0, "EvidenceCount": 2, "RevisionCount": 1, "IsUsable": 0, "IsProofEligible": 0, "DescendantCount": 0, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "F17", "Statement": "For the words 01 and 10 at onsets 4..46: the death window, survivors, the violated cone cells with counts, the common killing cells, whether the edge cell is among them, and t*(T).", "ReportedStatus": "FINITE_VERIFIED", "ProofSection": "", "Kind": "Finite check", "IntroducedInLoop": "effortless-18", "Name": "F17", "StatusGroup": "Checked", "PremiseCount": 3, "DependentCount": 0, "EvidenceCount": 1, "RevisionCount": 0, "IsUsable": 1, "IsProofEligible": 0, "DescendantCount": 0, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "B7", "Statement": "B6 for the period-2 words 01 and 10: for every onset T>=2, each TW row for a 2-periodic center violates a one-time constraint at or after 2T-1 (equivalently, the Rule 30 center is not eventually 2-periodic).", "ReportedStatus": "OPEN", "ProofSection": "", "Kind": "Bridge obligation", "IntroducedInLoop": "effortless-19", "Name": "B7", "StatusGroup": "Open", "PremiseCount": 3, "DependentCount": 1, "EvidenceCount": 4, "RevisionCount": 0, "IsUsable": 0, "IsProofEligible": 0, "DescendantCount": 5, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "B8", "Statement": "B6 for every nonconstant word of least period p>=3.", "ReportedStatus": "OPEN", "ProofSection": "", "Kind": "Bridge obligation", "IntroducedInLoop": "effortless-19", "Name": "B8", "StatusGroup": "Open", "PremiseCount": 3, "DependentCount": 1, "EvidenceCount": 2, "RevisionCount": 0, "IsUsable": 0, "IsProofEligible": 0, "DescendantCount": 5, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "H32", "Statement": "The dyadic wall is exact for period 2 past onset 36: for a=01 and every onset 47<=T<=50 the left-cone relaxation dies at window exactly 64, and for a=10 at exactly 65.", "ReportedStatus": "FINITE_VERIFIED", "ProofSection": "", "Kind": "Hypothesis", "IntroducedInLoop": "effortless-19", "Name": "H32", "StatusGroup": "Checked", "PremiseCount": 4, "DependentCount": 0, "EvidenceCount": 2, "RevisionCount": 1, "IsUsable": 1, "IsProofEligible": 0, "DescendantCount": 0, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "F18", "Statement": "L(T) for the words 01 and 10 at every onset 2<=T<=50 (loop 18 data plus onsets 2, 3 and 47..50 computed here with cap 2^26), with survivors at the death step.", "ReportedStatus": "FINITE_VERIFIED", "ProofSection": "", "Kind": "Finite check", "IntroducedInLoop": "effortless-19", "Name": "F18", "StatusGroup": "Checked", "PremiseCount": 2, "DependentCount": 0, "EvidenceCount": 1, "RevisionCount": 0, "IsUsable": 1, "IsProofEligible": 0, "DescendantCount": 0, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "H33", "Statement": "The 64-wall is exactly the TW boundary phenomenon: for the words 011,101,110 (pinned window 66) and 0111,1011,1101,1110 (pinned window 64) the death window keeps its pinned value from the first pinned onset through T=63 and exceeds it at T=64,65,66; for 01 and 10 at onsets 51 and 52 it stays at 64 and 65.", "ReportedStatus": "FALSIFIED", "ProofSection": "", "Kind": "Hypothesis", "IntroducedInLoop": "effortless-20", "Name": "H33", "StatusGroup": "Falsified", "PremiseCount": 4, "DependentCount": 0, "EvidenceCount": 2, "RevisionCount": 1, "IsUsable": 0, "IsProofEligible": 0, "DescendantCount": 0, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "F19", "Statement": "Structure of the 64-wall for the word 01 at onsets 37..46: forced cells on the death ray (none in the cone interior), tie classes by column (columns 1-3 tied, 4-5 partly, 6 onward untied), GF(2) independence of the 33 one-time functions over all rows for T<=18; and the L(T) table of H33 for period-3 and period-4 words at onsets 44..66.", "ReportedStatus": "FINITE_VERIFIED", "ProofSection": "", "Kind": "Finite check", "IntroducedInLoop": "effortless-20", "Name": "F19", "StatusGroup": "Checked", "PremiseCount": 4, "DependentCount": 0, "EvidenceCount": 2, "RevisionCount": 0, "IsUsable": 1, "IsProofEligible": 0, "DescendantCount": 0, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "H34", "Statement": "With every settled left-edge diagonal imposed on the periodic-center relaxation (exact values, or periodicity only), the death window exceeds the settled frontier by at most 8 (exact) or 16 (periodic only) for the words 01 and 10 at every onset 8<=T<=160 the search completes: the clash with the settled zone is local.", "ReportedStatus": "FALSIFIED", "ProofSection": "", "Kind": "Hypothesis", "IntroducedInLoop": "effortless-21", "Name": "H34", "StatusGroup": "Falsified", "PremiseCount": 4, "DependentCount": 0, "EvidenceCount": 2, "RevisionCount": 1, "IsUsable": 0, "IsProofEligible": 0, "DescendantCount": 0, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "F20", "Statement": "Settled-zone relaxation table for the words 01 and 10, exact and periodicity-only modes, onsets 8..160: frontier, death window, excess, peak live set, failing columns; the true lattice satisfies every imposed constraint to time 400.", "ReportedStatus": "FINITE_VERIFIED", "ProofSection": "", "Kind": "Finite check", "IntroducedInLoop": "effortless-21", "Name": "F20", "StatusGroup": "Checked", "PremiseCount": 4, "DependentCount": 0, "EvidenceCount": 1, "RevisionCount": 0, "IsUsable": 1, "IsProofEligible": 0, "DescendantCount": 0, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "TX", "Statement": "The left half x(i,t), i<=-1, is a function of c(0..t-1) and the seed, and whenever c(t)=1 the forward rule forces c(t+1)=NOT x(-1,t): the center is left-consistent.", "ReportedStatus": "PROVED_HUMAN_READABLE", "ProofSection": "research/loop-22-left-consistent/PROOFS.md \u00a7TX", "Kind": "Theorem", "IntroducedInLoop": "effortless-22", "Name": "TX", "StatusGroup": "Proved", "PremiseCount": 2, "DependentCount": 8, "EvidenceCount": 1, "RevisionCount": 0, "IsUsable": 1, "IsProofEligible": 1, "DescendantCount": 9, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "B9", "Statement": "No left-consistent sequence (c(0)=1, and c(t+1)=NOT x(-1,t) whenever c(t)=1, with x the left half it generates from the seed) ends in a periodic tail with a nonconstant word.", "ReportedStatus": "PROVED_HUMAN_READABLE", "ProofSection": "", "Kind": "Bridge obligation", "IntroducedInLoop": "effortless-22", "Name": "B9", "StatusGroup": "Proved", "PremiseCount": 3, "DependentCount": 1, "EvidenceCount": 4, "RevisionCount": 1, "IsUsable": 1, "IsProofEligible": 1, "DescendantCount": 2, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "H35", "Statement": "For the words 01 and 10 and every onset 4<=T<=46, every left-consistent prefix c(0..T-1) is killed by the 2-periodic tail before time 2T-1, inside the zone where the free-row relaxation provably cannot kill (TW).", "ReportedStatus": "FALSIFIED", "ProofSection": "", "Kind": "Hypothesis", "IntroducedInLoop": "effortless-22", "Name": "H35", "StatusGroup": "Falsified", "PremiseCount": 2, "DependentCount": 0, "EvidenceCount": 1, "RevisionCount": 1, "IsUsable": 0, "IsProofEligible": 0, "DescendantCount": 0, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "H36", "Statement": "For every nonconstant primitive word of period 3 or 4 and every onset 4<=T<=32, every left-consistent prefix is killed by the periodic tail before time 2T-1.", "ReportedStatus": "FALSIFIED", "ProofSection": "", "Kind": "Hypothesis", "IntroducedInLoop": "effortless-22", "Name": "H36", "StatusGroup": "Falsified", "PremiseCount": 2, "DependentCount": 0, "EvidenceCount": 1, "RevisionCount": 1, "IsUsable": 0, "IsProofEligible": 0, "DescendantCount": 0, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "F21", "Statement": "Seeded relaxation table: for the words 01, 10 (onsets 4..46) and every primitive word of period 3 and 4 (onsets 4..32), the number of left-consistent prefixes, survivors, and the largest and mean death excess t*-T with its histogram; tree growth ratio 1.4981 per step.", "ReportedStatus": "FINITE_VERIFIED", "ProofSection": "", "Kind": "Finite check", "IntroducedInLoop": "effortless-22", "Name": "F21", "StatusGroup": "Checked", "PremiseCount": 1, "DependentCount": 0, "EvidenceCount": 1, "RevisionCount": 0, "IsUsable": 1, "IsProofEligible": 0, "DescendantCount": 0, "Predicate": null, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1 },
      { "AssertionId": "H37", "Statement": "For some E>=12, the near-center windows (c(t), x(-1..-E,t)) shown by left-consistent sequences at t=45 miss at least half of the 2^(E+1) possible windows.", "ReportedStatus": "FINITE_VERIFIED", "ProofSection": "", "Kind": "Hypothesis", "IntroducedInLoop": "effortless-23", "Name": "H37", "StatusGroup": "Checked", "PremiseCount": 1, "DependentCount": 0, "EvidenceCount": 2, "RevisionCount": 1, "IsUsable": 1, "IsProofEligible": 0, "DescendantCount": 0, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1, "Predicate": null },
      { "AssertionId": "H38", "Statement": "There is an E<=30 such that every width-(E+1) near-center window shown by a left-consistent sequence at any time 19<=t<=45 dies within E-1 steps under the tail 01 and under the tail 10 (the finite part K(E) of B9 for period 2).", "ReportedStatus": "FINITE_VERIFIED", "ProofSection": "", "Kind": "Hypothesis", "IntroducedInLoop": "effortless-23", "Name": "H38", "StatusGroup": "Checked", "PremiseCount": 1, "DependentCount": 0, "EvidenceCount": 2, "RevisionCount": 1, "IsUsable": 1, "IsProofEligible": 0, "DescendantCount": 0, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1, "Predicate": null },
      { "AssertionId": "F22", "Statement": "Near-center window language of left-consistent sequences for E=4..30 (even) and t=19..45: language sizes, stability in t (E<=22), the smallest missing windows, and the windows surviving E-1 steps under each period-2 tail.", "ReportedStatus": "FINITE_VERIFIED", "ProofSection": "", "Kind": "Finite check", "IntroducedInLoop": "effortless-23", "Name": "F22", "StatusGroup": "Checked", "PremiseCount": 1, "DependentCount": 0, "EvidenceCount": 1, "RevisionCount": 0, "IsUsable": 1, "IsProofEligible": 0, "DescendantCount": 0, "PredicateVerdict": "NO INSTANCES", "PredicateIsFinitelyDecidable": 1, "Predicate": null }
