      { "name": "PrerequisiteId", "datatype": "string", "type": "raw", "nullable": false, "Description": "PrerequisiteId" },
      { "name": "Name", "datatype": "string", "type": "calculated", "nullable": false, "Description": "Name", "formula": "={{PrerequisiteId}}" },
      { "name": "ConclusionKey", "datatype": "string", "type": "relationship", "nullable": false, "Description": "The assessment this transitive premise feeds.", "RelatedTo": "Assessments" },
      { "name": "Premise", "datatype": "string", "type": "relationship", "nullable": false, "Description": "A transitive ancestor of the conclusion (including itself).", "RelatedTo": "Assertions" },
      { "name": "PremiseUsable", "datatype": "integer", "type": "lookup", "nullable": false, "Description": "PremiseUsable", "formula": "=INDEX(Assertions!{{IsUsable}},MATCH({{Premise}},Assertions!{{AssertionId}},0))" },
      { "name": "PremiseProofEligible", "datatype": "integer", "type": "lookup", "nullable": false, "Description": "PremiseProofEligible", "formula": "=INDEX(Assertions!{{IsProofEligible}},MATCH({{Premise}},Assertions!{{AssertionId}},0))" },
      { "name": "Blocked", "datatype": "integer", "type": "calculated", "nullable": false, "Description": "Blocked", "formula": "=1-{{PremiseUsable}}" },
      { "name": "ProofBlocked", "datatype": "integer", "type": "calculated", "nullable": false, "Description": "ProofBlocked", "formula": "=1-{{PremiseProofEligible}}" },
      { "name": "IsSelf", "datatype": "integer", "type": "calculated", "nullable": true, "Description": "1 for the row pairing a claim with itself.", "formula": "=IF({{ConclusionKey}}={{Premise}},1,0)" },
      { "name": "IsBlockingAncestor", "datatype": "integer", "type": "calculated", "nullable": true, "Description": "1 when this ancestor is not usable and so blocks the conclusion.", "formula": "=IF(AND({{Blocked}}=1,{{IsSelf}}=0),1,0)" }
