      { "name": "ClaimCount", "datatype": "integer", "type": "aggregation", "nullable": false, "Description": "ClaimCount", "formula": "=COUNTIFS(Assessments!{{ProjectKey}},{{DashboardId}})" },
      { "name": "BlockedCount", "datatype": "integer", "type": "aggregation", "nullable": false, "Description": "BlockedCount", "formula": "=COUNTIFS(Assessments!{{ProjectKey}},{{DashboardId}},Assessments!{{CurrentStatus}},\"BLOCKED\")" },
      { "name": "CompletedNativeLoops", "datatype": "integer", "type": "aggregation", "nullable": false, "Description": "CompletedNativeLoops", "formula": "=COUNTIFS(Loops!{{ProjectKey}},{{DashboardId}},Loops!{{Kind}},\"EFFORTLESS\",Loops!{{State}},\"VERIFIED\")" },
      { "name": "EvidenceGapCount", "datatype": "integer", "type": "aggregation", "nullable": false, "Description": "Finite-verified claims with no linked evidence.", "formula": "=SUMIFS(Assessments!{{EvidenceGap}},Assessments!{{ProjectKey}},{{DashboardId}})" },
      { "name": "ProvedCount", "datatype": "integer", "type": "aggregation", "nullable": true, "Description": "Claims proved, rederived or definitional.", "formula": "=COUNTIFS(Assessments!{{ProjectKey}},{{DashboardId}},Assessments!{{StatusGroup}},\"Proved\")" },
      { "name": "CheckedCount", "datatype": "integer", "type": "aggregation", "nullable": true, "Description": "Claims verified by finite computation only.", "formula": "=COUNTIFS(Assessments!{{ProjectKey}},{{DashboardId}},Assessments!{{StatusGroup}},\"Checked\")" },
      { "name": "FalsifiedCount", "datatype": "integer", "type": "aggregation", "nullable": true, "Description": "Hypotheses shown false.", "formula": "=COUNTIFS(Assessments!{{ProjectKey}},{{DashboardId}},Assessments!{{StatusGroup}},\"Falsified\")" },
      { "name": "OpenCount", "datatype": "integer", "type": "aggregation", "nullable": true, "Description": "Claims still open.", "formula": "=COUNTIFS(Assessments!{{ProjectKey}},{{DashboardId}},Assessments!{{StatusGroup}},\"Open\")" },
      { "name": "AtRiskCount", "datatype": "integer", "type": "aggregation", "nullable": true, "Description": "Established claims resting on something not established. Should be 0.", "formula": "=SUMIFS(Assessments!{{IsAtRisk}},Assessments!{{ProjectKey}},{{DashboardId}})" },
      { "name": "OpenPrizeProblemCount", "datatype": "integer", "type": "aggregation", "nullable": true, "Description": "Prize problems not yet resolved.", "formula": "=COUNTIFS(Assessments!{{ProjectKey}},{{DashboardId}},Assessments!{{Kind}},\"Prize problem\",Assessments!{{StatusGroup}},\"Open\")" },
      { "name": "RunningLoopCount", "datatype": "integer", "type": "aggregation", "nullable": true, "Description": "Loops in progress right now.", "formula": "=COUNTIFS(Loops!{{ProjectKey}},{{DashboardId}},Loops!{{State}},\"RUNNING\")" },
      { "name": "LegacyLoopCount", "datatype": "integer", "type": "aggregation", "nullable": true, "Description": "Research cycles from v05, before native builds.", "formula": "=COUNTIFS(Loops!{{ProjectKey}},{{DashboardId}},Loops!{{Kind}},\"LEGACY_RESEARCH\")" },
      { "name": "ConformanceMismatchCount", "datatype": "integer", "type": "aggregation", "nullable": true, "Description": "Optimizer claims the model disagrees with. Must be 0.", "formula": "=COUNTIFS(AcceleratorClaims!{{IsMatch}},0)" },
      { "name": "PredicatesFailingAnInstance", "datatype": "integer", "type": "aggregation", "nullable": true, "Description": "Predicates with at least one failing bounded instance.", "formula": "=COUNTIFS(Predicates!{{IsFinitelyDecidable}},0,Predicates!{{FailingCount}},\">0\")" }
