      { "name": "Variable", "datatype": "string", "type": "relationship", "nullable": false, "Description": "The variable bound.", "RelatedTo": "Variables" },
      { "name": "Condition", "datatype": "string", "type": "raw", "nullable": true, "Description": "The restriction on the variable, if any." },
      { "name": "Symbol", "datatype": "string", "type": "lookup", "nullable": true, "Description": "How the problem writes the variable.", "formula": "=INDEX(Variables!{{Symbol}},MATCH({{Variable}},Variables!{{VariableId}},0))" },
      { "name": "DomainTable", "datatype": "string", "type": "lookup", "nullable": true, "Description": "The table holding its values in the model.", "formula": "=INDEX(Variables!{{DomainTable}},MATCH({{Variable}},Variables!{{VariableId}},0))" },
      { "name": "IsUnbounded", "datatype": "integer", "type": "lookup", "nullable": true, "Description": "1 when it ranges over an infinite domain.", "formula": "=INDEX(Variables!{{IsUnboundedInProblem}},MATCH({{Variable}},Variables!{{VariableId}},0))" }
