      "Assertions.StatusGroup": {
        "table": "Assertions",
        "field": "StatusGroup",
        "kind": "formula",
        "rule": "The assertion's status group is determined by the following priority:\n1. “Proved”, if at least one of the following holds: the reported status is “DEFINITION”; the reported status is “PROVED_HUMAN_READABLE”; or the reported status is “REDERIVED_KNOWN”;\n2. “Checked”, if the reported status is “FINITE_VERIFIED”;\n3. “Falsified”, if the reported status is “FALSIFIED”;\n4. “Superseded”, if the reported status is “SUPERSEDED”;\n5. in all other cases, “Open”.",
        "mechanical": false,
        "refs": [
          {
            "table": "Assertions",
            "field": "ReportedStatus",
            "label": "reported status"
          }
        ],
        "structure": {
          "kind": "priority",
          "headline": "The assertion's status group is determined by the following priority:",
          "cases": [
            {
              "value": "“Proved”",
              "when": {
                "kind": "any",
                "children": [
                  {
                    "kind": "leaf",
                    "text": "the reported status is “DEFINITION”"
                  },
                  {
                    "kind": "leaf",
                    "text": "the reported status is “PROVED_HUMAN_READABLE”"
                  },
                  {
                    "kind": "leaf",
                    "text": "the reported status is “REDERIVED_KNOWN”"
                  }
                ]
              }
            },
            {
              "value": "“Checked”",
              "when": {
                "kind": "leaf",
                "text": "the reported status is “FINITE_VERIFIED”"
              }
            },
            {
              "value": "“Falsified”",
              "when": {
                "kind": "leaf",
                "text": "the reported status is “FALSIFIED”"
              }
            },
            {
              "value": "“Superseded”",
              "when": {
                "kind": "leaf",
                "text": "the reported status is “SUPERSEDED”"
              }
            },
            {
              "value": "“Open”",
              "when": null
            }
          ],
          "children": null
        }
      },
